import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.iXqqCa-C.js";const o="/images/agent-styles.webp",u=JSON.parse('{"title":"对话风格","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/styles.md","filePath":"guide/agent/styles.md","lastUpdated":1793501934000}'),n={name:"guide/agent/styles.md"};function l(i,a,d,h,g,p){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="对话风格" tabindex="-1">对话风格 <a class="header-anchor" href="#对话风格" aria-label="Permalink to &quot;对话风格&quot;">​</a></h1><p>对话风格决定角色<strong>怎么说话</strong>：语气、人称、句长、是否带动作描写和旁白。同一个角色可以搭配不同风格。</p><p>发送消息前必须为会话选择一个对话风格。自己创建的风格可以直接使用；发布到广场供他人使用，需要和角色一样单独提交审核。</p><h2 id="获取风格" tabindex="-1">获取风格 <a class="header-anchor" href="#获取风格" aria-label="Permalink to &quot;获取风格&quot;">​</a></h2><ul><li><strong>自己创建</strong>：见<a href="#创建风格">创建风格</a>。</li><li><strong>从广场加入</strong>：在广场的「对话风格」标签页浏览别人发布的风格，点「加入我的列表」即可使用。来自广场的风格带有标识，可随时移除。</li></ul><p><img src="'+o+'" alt="风格广场"></p><h2 id="创建风格" tabindex="-1">创建风格 <a class="header-anchor" href="#创建风格" aria-label="Permalink to &quot;创建风格&quot;">​</a></h2><p>进入「智能体 → 创作 → 对话风格」新建：</p><ul><li><strong>风格名称</strong>：列表里显示的名字。</li><li><strong>简介</strong>：只用于展示，<strong>不会发送给模型</strong>。</li><li><strong>风格说明（正文）</strong>：写入系统提示，描述语气、人称、回复长短、是否使用动作描写或旁白、标点习惯等。</li></ul><p>风格与角色设定<strong>同时</strong>生效：角色设定决定角色是谁，风格决定角色怎么说话。</p><h2 id="编辑与发布" tabindex="-1">编辑与发布 <a class="header-anchor" href="#编辑与发布" aria-label="Permalink to &quot;编辑与发布&quot;">​</a></h2><p>风格和角色一样支持：草稿测试、版本管理、提交审核、发布到广场。流程见<a href="/guide/agent/create#测试与发布">创作角色</a>。</p><h2 id="在会话中切换" tabindex="-1">在会话中切换 <a class="header-anchor" href="#在会话中切换" aria-label="Permalink to &quot;在会话中切换&quot;">​</a></h2><p>会话的「对话风格」标签页可以随时切换当前会话的风格，不影响角色设定。</p>',14)])])}const _=t(n,[["render",l]]);export{u as __pageData,_ as default};
